// A simple Counter actor.

persistent actor class Counter(i : Int) {
  transient var c = i;

  // Decrement counter
  public func dec() : () {
    show("dec", c);
    c -= 1;
  };

  // Read counter, asynchronous
  public func read() : async Int { c };
};

// Dummy function to show intermediate value in trace.
