// Create an actor.
let c = await Counter(10);

// Issue ten `dec` messages.
func testDec() : async () {
  var i : Int = 10;
  while i > 0 {
    c.dec();
    i -= 1;
  }
};

ignore testDec();

// Issue ten `dec` & `read` messages.
func testRead() : async () {

  // Dummy function to show intermediate value in trace.
  func showAsync(note : Text, a : async Int) {};

  var i : Int = 10;
  while i > 0 {
    c.dec();
    let t = c.read();
    showAsync("before", t);
    show("await", await t);
    showAsync("after", t);
    i -= 1;
  }
};

ignore testRead();

/* integer quicksort as top-level functions */

func swap(a : [var Int], i : Nat, j : Nat) {
  let temp = a[i];
  a[i] := a[j];
  a[j] := temp;
};

func partition(a : [var Int], lo : Nat, hi : Nat) : Nat {
  let pivot = a[lo];
  var i : Nat = lo;
  var j : Nat = hi;

  loop {
    while a[i] < pivot { i += 1 };
    while a[j] > pivot { j -= 1 };
    if i >= j { return j };
    swap(a, i, j);
    i += 1;
    j -= 1;
  };
};

func quicksort(a : [var Int], lo : Nat, hi : Nat) {
  if lo < hi {
    let p = partition(a, lo, hi);
    quicksort(a, lo, p);
    quicksort(a, p + 1, hi);
  };
};

